import java.util.*;

public class MaxUniqueCharFinder {
    /**
     * Finds the word with the maximum number of unique characters from a list of words.
     * If multiple words have the same number of unique characters, returns the one that comes first lexicographically.
     * 
     * @param words An array of words to search through.
     * @return The word with the maximum number of unique characters.
     */
    public static String findMaxUniqueChars(String[] words) {
        String maxWord = "";
        int maxUniqueChars = 0;

        for (String word : words) {
            int uniqueChars = word.length() - Arrays.stream(word.split("")).distinct().count();
            if (uniqueChars > maxUniqueChars || (uniqueChars == maxUniqueChars && word.compareTo(maxWord) < 0)) {
                maxWord = word;
                maxUniqueChars = uniqueChars;
            }
        }

        return maxWord;
    }

    public static void main(String[] args) {
        // Check function with provided data points
        assert findMaxUniqueChars(new String[]{"name", "of", "string"}) == "string";
        assert findMaxUniqueChars(new String[]{"name", "enam", "game"}) == "enam";
        assert findMaxUniqueChars(new String[]{"aaaaaaa", "bb", "cc"}) == ""aaaaaaa;
        System.out.println("All checks passed!");
    }
}
